import{_ as e,c as a,a0 as i,o as r}from"./chunks/framework.B6JXc2q-.js";const m=JSON.parse('{"title":"长期凭据生命周期历史实验","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/2026-10-24-auth-pass-token-lifecycle-experiment.md","filePath":"maintenance/2026-10-24-auth-pass-token-lifecycle-experiment.md"}'),d={name:"maintenance/2026-10-24-auth-pass-token-lifecycle-experiment.md"};function n(o,t,l,h,c,s){return r(),a("div",null,t[0]||(t[0]=[i('<h1 id="长期凭据生命周期历史实验" tabindex="-1">长期凭据生命周期历史实验 <a class="header-anchor" href="#长期凭据生命周期历史实验" aria-label="Permalink to &quot;长期凭据生命周期历史实验&quot;">​</a></h1><p>原实验开始：2026-10-24。2026-11-22 整理为脱敏历史记录，并更正旧结论。</p><h2 id="目的与条件" tabindex="-1">目的与条件 <a class="header-anchor" href="#目的与条件" aria-label="Permalink to &quot;目的与条件&quot;">​</a></h2><p>调查扫码后周期性掉线是否来自遗漏的长期凭据轮换，还是服务端拒绝当前凭据。测试保持约12小时计划续期，记录换票成功与失败时间、是否存在凭据及是否轮换。真实凭据、指纹、长度、账号及响应原文不纳入公开记录。</p><h2 id="历史观察" tabindex="-1">历史观察 <a class="header-anchor" href="#历史观察" aria-label="Permalink to &quot;历史观察&quot;">​</a></h2><table tabindex="0"><thead><tr><th>周期</th><th>扫码起点（JST）</th><th>首次续期失败（JST）</th><th>相对时长</th></tr></thead><tbody><tr><td>前一周期</td><td>2026-10-19 20:41</td><td>2026-10-23 09:04</td><td>约84.38小时</td></tr><tr><td>10月24日起周期</td><td>2026-10-24 23:29:36</td><td>2026-10-28 11:48</td><td>约84.31小时</td></tr></tbody></table><p>两轮最后一次成功续期均约在72.3小时。10月24日起周期的第6次成功在10月27日23:46，第7次续期失败在10月28日11:48。</p><p>成功期间未观察到长期凭据轮换；失败响应包含删除指令及认证拒绝。应用不得将删除指令当作新长期凭据写入。</p><p>10月29日08:01另一次扫码后曾检查 <code>_get_location</code> 路径；当时的实验未建立可用的替代长期续期方案。该结果仅描述当时路径和条件，不证明所有其他实现均不可行。</p><h2 id="更正与证据限制" tabindex="-1">更正与证据限制 <a class="header-anchor" href="#更正与证据限制" aria-label="Permalink to &quot;更正与证据限制&quot;">​</a></h2><p>旧记录曾将重复的72～84小时失效窗口描述为“服务端硬限”，并过早排除身份/风控影响。该推断超出证据：12小时采样只能界定当时最后成功到首次失败的区间，不能确定服务端固定TTL，也不能排除请求身份变化。</p><p>2026年11月的固定身份候选在同一轮凭据上持续约15天20小时，并完成31次验证后提交，已超过旧窗口。详见 <code>2026-11-10-pass-token-identity-freeze-observation.md</code>。身份一致性是当前得到观察支持的修复方向；唯一根因仍无服务端证据。</p><h2 id="保留的工程结论" tabindex="-1">保留的工程结论 <a class="header-anchor" href="#保留的工程结论" aria-label="Permalink to &quot;保留的工程结论&quot;">​</a></h2><ul><li>长期凭据年龄与短会话保存时间独立记录。</li><li>只有经验证的候选才能原子提交；空值或删除标记不能覆盖旧凭据。</li><li>续期被拒时区分长期续期能力与当前短会话可用性。</li><li>保留固定身份及原刷新周期，不引入隐式密码登录。</li><li>不再以历史窗口向用户推算到期时间。</li></ul>',14)]))}const u=e(d,[["render",n]]);export{m as __pageData,u as default};
